/* ═══════════════════════════════════════════════════════════
   PIP Player, the interface dictionaries.

   One file rather than JSON fetched on demand: the player has to work
   when opened straight from a file, and the browser forbids fetch over
   file://. So every language lives here and loads through a plain
   script tag.

   The names of audio track languages are NOT kept here. Intl.DisplayNames
   returns them, three letter ffprobe codes included (rus, eng, jpn).
   Maintaining that table by hand in ten languages would mean rewriting
   what the browser already has.

   Plural forms: a value can be an object instead of a string, keyed by
   Intl.PluralRules (one/few/many/other).
   ═══════════════════════════════════════════════════════════ */
