  'feat.pip': 'Picture-in-Picture',
  'feat.pip.1': 'Browser mode: a window with no address bar, browser controls. Previous and next work through the Media Session API.',
  'feat.pip.2': 'Extended mode: the video goes into the floating window with the seek bar, episode switching, volume, audio track and subtitle pickers. The main window stays fully working: speed, repeat, auto-advance, the queue, the settings and fullscreen remain there. A change in one window shows in the other at once.',
  'feat.pip.2.1': 'Hotkeys work inside the floating window too.',
  'feat.pip.2.2': 'Chrome draws the site address bar on top of this window and it cannot be removed, so browser mode is the default.',
  'feat.pip.3': 'In both modes the main window shows a placeholder with a “Bring it back” button where the video was. If the queue was closed, it opens in the main window while Picture-in-Picture is on, so episodes can be switched from there, and closes again once the floating window is closed.',
  'feat.audio': 'Sound and subtitles',
  'feat.audio.1': 'The track list shows language, studio name, codec, channel layout, bitrate and sample rate.',
  'feat.audio.2': 'The audio track choice survives switching files. It looks for the same set of tracks first, then a matching language and studio, then language alone.',
  'feat.audio.3': 'Text subtitles (SRT, ASS, SSA, WebVTT, mov_text) are converted to WebVTT and attached to the video. Image subtitles (PGS, VOBSUB) are listed but cannot be picked.',
  'feat.audio.4': 'The subtitle choice survives the same way. Size, backing and height are adjustable.',
  'feat.audio.5': 'Track choice and subtitles work only with the local server.',
  'feat.bridge': 'The local ffmpeg server',
  'feat.bridge.1': 'One ffmpeg pass per file and track: the video is stream-copied, only the chosen audio track is re-encoded to stereo AAC.',
  'feat.bridge.2': 'The result is served with HTTP Range. Seeking is done by the browser.',
  'feat.bridge.3': 'The next file is prepared in the background, keeping the chosen audio track.',
  'feat.bridge.4': 'Hardware encoding if the video does have to be re-encoded: videotoolbox on macOS, NVENC, Quick Sync or AMF on Windows, NVENC or Quick Sync on Linux. On failure the pass is repeated on libx264.',
  'feat.bridge.5': 'Files the browser decodes on its own are served untouched. Prepared files sit in a cache and are evicted by least recent use.',
  'feat.bridge.6': 'Dropped files are located on disk by name and size, and the rest of the same folder comes with them. Folders where files were found before are checked first.',
  'feat.bridge.7': 'The cache limit is set with a bar in the settings, from 4 GB up to what the disk can hold.',
  'feat.play': 'Playback and queue',
  'feat.play.1': 'Adding: files, a folder, drag-and-drop, the disk browser. A picked or dropped folder is read with its subfolders.',
  'feat.play.2': 'Sort by name, reverse, shuffle, change the order of files by hand.',
  'feat.play.3': 'Two list views: rows and a grid. A row has a frame from the file in the video’s proportions, the name, duration, size and track count. The grid has frames only.',
  'feat.play.4': 'The crosshair button in the queue header scrolls the list to the current file. When another file starts, the list scrolls to it by itself, which can be turned off in the settings.',
  'feat.play.5': 'Auto-advance to the next file. Repeat of the queue or of one file. A summary card at the end.',
  'feat.play.6': 'Speed from 0.5× to 2×. Seeking by mouse and keyboard, a time hint above the bar, a buffered marker.',
  'feat.play.7': 'The watch position is remembered for each file and marked in the queue by a thin line at the bottom of the frame. The volume is remembered too.',
  'feat.play.8': 'With the local server, a page reload brings back the queue and the file you stopped on.',
  'feat.ui': 'Interface',
  'feat.ui.1': 'Ten languages, picked from the browser.',
  'feat.ui.2': 'Two typefaces.',
  'feat.ui.3': 'Hotkeys are bound to physical key codes and work in any keyboard layout.',
  'feat.ui.4': 'The control panel hides itself, the favicon shows the state. In the settings: file panel behaviour, changing the order of files by hand, scrolling the queue to the current file, hiding the controls on auto-advance, typeface, language.',
  'feat.ui.5': 'When room is short, next to the open queue for one, the control panel tightens: speed, repeat and auto-advance fold into a gear at the bottom right and open on hover, and the studio name on the audio track button gets shorter. With fewer than four letters left, only the icon stays on the button.',
  'feat.ui.6': 'Long file names and paths are cut on the right, and the tooltip on hover shows them whole.',
