  'empty.title': 'Link einfügen',
  'empty.text': 'Ein Link zu einem Anime oder zu einer Folge<br>Lapka findet die Folgen und die Synchros selbst',
  'about.lead': 'Lapka ist ein lokaler Anime-Player.',

  'feat.pip': 'Bild-in-Bild',
  'feat.pip.1': 'Browser-Modus: ein Fenster ohne Adressleiste, Bedienelemente des Browsers. Vor und zurück laufen über die Media Session API.',
  'feat.pip.2': 'Erweiterter Modus: das Video geht ins schwebende Fenster, mit Zeitleiste, Folgenwechsel, Lautstärke, Auswahl von Tonspur und Untertiteln. Das Hauptfenster bleibt voll bedienbar: Tempo, Wiederholung, automatischer Wechsel, Warteschlange, Einstellungen und Vollbild bleiben dort. Änderungen in einem Fenster sind sofort im anderen zu sehen.',
  'feat.pip.2.1': 'Die Tastenkürzel wirken auch im schwebenden Fenster.',
  'feat.pip.2.2': 'Über diesem Fenster zeichnet Chrome die Adressleiste der Seite, und sie lässt sich nicht entfernen. Deshalb ist der Browser-Modus voreingestellt.',
  'feat.pip.3': 'In beiden Modi steht im Hauptfenster anstelle des Videos ein Platzhalter mit der Schaltfläche „Zurückholen“. War die Warteschlange geschlossen, öffnet sie sich für die Dauer von Bild-in-Bild im Hauptfenster, damit sich die Folgen von dort wechseln lassen, und schließt sich wieder, sobald das schwebende Fenster geschlossen ist.',
  'feat.audio': 'Ton und Untertitel',
  'feat.audio.1': 'In der Spurliste stehen Sprache, Studioname, Codec, Kanalzahl, Bitrate und Abtastrate.',
  'feat.audio.2': 'Die Wahl der Tonspur bleibt beim Dateiwechsel erhalten. Gesucht wird erst dieselbe Spurliste, dann eine Übereinstimmung von Sprache und Studio, dann nur der Sprache.',
  'feat.audio.3': 'Text-Untertitel (SRT, ASS, SSA, WebVTT, mov_text) werden nach WebVTT konvertiert und ans Video gehängt. Bild-Untertitel (PGS, VOBSUB) stehen in der Liste, lassen sich aber nicht wählen.',
  'feat.audio.4': 'Die Untertitelwahl bleibt genauso erhalten. Größe, Hinterlegung und Höhe sind einstellbar.',
  'feat.audio.5': 'Tonspurwahl und Untertitel funktionieren nur mit dem lokalen Server.',
  'feat.bridge': 'Der lokale ffmpeg-Server',
  'feat.bridge.1': 'Ein ffmpeg-Durchlauf je Datei und Spur: das Video wird per Stream Copy übernommen, umkodiert wird nur die gewählte Tonspur, nach Stereo-AAC.',
  'feat.bridge.2': 'Das Ergebnis wird mit HTTP Range ausgeliefert. Das Springen übernimmt der Browser.',
  'feat.bridge.3': 'Die nächste Datei wird im Hintergrund vorbereitet, mit der gewählten Tonspur.',
  'feat.bridge.4': 'Hardware-Kodierung, falls das Video doch neu kodiert werden muss: videotoolbox unter macOS, NVENC, Quick Sync oder AMF unter Windows, NVENC oder Quick Sync unter Linux. Bei einem Fehler wird der Durchlauf mit libx264 wiederholt.',
  'feat.bridge.5': 'Dateien, die der Browser selbst dekodiert, gehen unbearbeitet durch. Vorbereitetes liegt in einem Cache und wird nach letzter Nutzung verdrängt.',
  'feat.bridge.6': 'Hereingezogene Dateien findet der Server über Name und Größe, den Rest desselben Ordners nimmt er mit. Ordner, in denen schon Dateien gefunden wurden, prüft er zuerst.',
  'feat.bridge.7': 'Das Limit des Zwischenspeichers stellt ein Balken in den Einstellungen ein: von 4 GB bis zu dem, was die Festplatte fassen kann.',
  'feat.play': 'Wiedergabe und Warteschlange',
  'feat.play.1': 'Hinzufügen: Dateien, ein Ordner, Ziehen und Ablegen, der Festplatten-Browser. Ein gewählter oder hereingezogener Ordner wird mit seinen Unterordnern eingelesen.',
  'feat.play.2': 'Sortieren nach Name, umkehren, mischen, Reihenfolge der Dateien von Hand ändern.',
  'feat.play.3': 'Zwei Listenansichten: Zeilen und Raster. In einer Zeile stehen ein Bild aus der Datei im Seitenverhältnis des Videos, der Name, die Dauer, die Größe und die Spurzahl. Im Raster nur Bilder.',
  'feat.play.4': 'Die Schaltfläche mit dem Fadenkreuz im Kopf der Warteschlange scrollt die Liste zur aktuellen Datei. Beginnt eine andere Datei, scrollt die Liste von selbst zu ihr, das lässt sich in den Einstellungen abschalten.',
  'feat.play.5': 'Automatischer Wechsel zur nächsten Datei. Wiederholung der Warteschlange oder einer Datei. Am Ende eine Abschlusskarte.',
  'feat.play.6': 'Tempo von 0.5× bis 2×. Springen mit Maus und Tastatur, ein Zeithinweis über der Leiste, eine Puffermarkierung.',
  'feat.play.7': 'Die Wiedergabeposition wird für jede Datei gemerkt und in der Warteschlange mit einer dünnen Linie am unteren Rand des Bildes markiert. Die Lautstärke wird ebenfalls gemerkt.',
  'feat.play.8': 'Mit dem lokalen Server kommen nach dem Neuladen der Seite die Warteschlange und die zuletzt gespielte Datei zurück.',
  'feat.ui': 'Oberfläche',
  'feat.ui.1': 'Zehn Sprachen, nach der Sprache des Browsers bestimmt.',
  'feat.ui.2': 'Zwei Schriftarten zur Wahl.',
  'feat.ui.3': 'Tastenkürzel hängen an physischen Tastencodes und funktionieren in jeder Belegung.',
  'feat.ui.4': 'Die Bedienleiste blendet sich selbst aus, den Zustand zeigt das Favicon. In den Einstellungen: Verhalten der Dateiliste, Reihenfolge der Dateien von Hand ändern, Scrollen der Warteschlange zur aktuellen Datei, Ausblenden der Bedienleiste beim automatischen Wechsel, Schriftart, Sprache.',
  'feat.ui.5': 'Wenn der Platz knapp wird, etwa neben der geöffneten Warteschlange, rückt die Bedienleiste zusammen: Tempo, Wiederholung und automatischer Wechsel klappen in ein Zahnrad unten rechts und öffnen sich beim Überfahren, der Studioname auf der Tonspur-Schaltfläche wird kürzer. Bleiben weniger als vier Buchstaben, zeigt die Schaltfläche nur das Symbol.',
  'feat.ui.6': 'Lange Dateinamen und Pfade werden rechts abgeschnitten, vollständig zeigt sie der Tooltip beim Überfahren.',
  'empty.files': 'Dateien wählen',
