  'hint.bridge': 'ffmpeg ist verfügbar. Hereingezogene Dateien findet der Server selbst auf der Festplatte. Klappt das nicht, fügen Sie sie über „Festplatte durchsuchen“ hinzu.',
  'hint.noFfmpeg': 'ffmpeg wurde nicht im PATH gefunden, MKV-Spuren lassen sich nicht auslesen.',
