  'help.title': 'Warum es keinen Ton gibt',
  'help.p1': 'In MKV-Releases liegt der Ton meist als <b>AC-3, E-AC-3 oder DTS</b> vor. Diese Codecs dekodiert der Browser nicht: das Bild läuft, der Ton schweigt. Eine andere Spur zu wählen hilft nicht: Chrome hat für lokale Dateien keine API zum Spurwechsel.',
  'help.p2': 'Gelöst wird das von einem lokalen Server auf Ihrem eigenen ffmpeg. Er liest die Spurliste und kodiert die gewählte Spur nach AAC um, während das Video ohne Neukompression durchgereicht wird.',
  'help.p3': 'Öffnen Sie dann <b>http://127.0.0.1:8777</b>. Es erscheinen die Schaltfläche „Festplatte durchsuchen“ und eine Liste der Tonspuren mit Sprachen.',

