  'empty.title': 'Collez un lien',
  'empty.text': 'Un lien vers un anime ou vers un épisode<br>Lapka trouve les épisodes et les doublages elle-même',
  'about.lead': 'Lapka est un lecteur d’anime local.',

  'feat.pip': 'Image dans l’image',
  'feat.pip.1': 'Mode navigateur : une fenêtre sans barre d’adresse, contrôles du navigateur. Précédent et suivant passent par l’API Media Session.',
  'feat.pip.2': 'Mode étendu : la vidéo passe dans la fenêtre flottante avec la barre de lecture, le changement d’épisode, le volume, le choix de la piste audio et des sous-titres. La fenêtre principale reste entièrement utilisable : la vitesse, la répétition, l’enchaînement, la file d’attente, les réglages et le plein écran y restent. Un changement dans une fenêtre se voit aussitôt dans l’autre.',
  'feat.pip.2.1': 'Les raccourcis marchent aussi dans la fenêtre flottante.',
  'feat.pip.2.2': 'Chrome affiche la barre d’adresse du site en haut de cette fenêtre et elle ne peut pas être retirée, c’est pourquoi le mode navigateur est celui par défaut.',
  'feat.pip.3': 'Dans les deux modes, la fenêtre principale affiche à la place de la vidéo un écran d’attente avec le bouton « Ramener ici ». Si la file d’attente était fermée, elle s’ouvre dans la fenêtre principale le temps de l’image dans l’image, pour changer d’épisode depuis là, puis se referme une fois la fenêtre flottante fermée.',
  'feat.audio': 'Son et sous-titres',
  'feat.audio.1': 'La liste des pistes indique la langue, le nom du studio, le codec, les canaux, le débit et la fréquence d’échantillonnage.',
  'feat.audio.2': 'Le choix de la piste audio se conserve d’un fichier à l’autre. On cherche d’abord la même liste de pistes, puis une correspondance de langue et de studio, puis de langue seule.',
  'feat.audio.3': 'Les sous-titres texte (SRT, ASS, SSA, WebVTT, mov_text) sont convertis en WebVTT et attachés à la vidéo. Les sous-titres en images (PGS, VOBSUB) figurent dans la liste mais ne peuvent pas être choisis.',
  'feat.audio.4': 'Le choix des sous-titres se conserve de la même façon. Taille, fond et hauteur sont réglables.',
  'feat.audio.5': 'Le choix de la piste et les sous-titres ne marchent qu’avec le serveur local.',
  'feat.bridge': 'Le serveur ffmpeg local',
  'feat.bridge.1': 'Une passe ffmpeg par fichier et par piste : la vidéo est copiée en flux, seule la piste audio choisie est réencodée en AAC stéréo.',
  'feat.bridge.2': 'Le résultat est servi avec HTTP Range. Le déplacement est fait par le navigateur.',
  'feat.bridge.3': 'Le fichier suivant se prépare en arrière-plan, avec la piste audio choisie.',
  'feat.bridge.4': 'Encodage matériel si la vidéo doit tout de même être réencodée : videotoolbox sur macOS, NVENC, Quick Sync ou AMF sur Windows, NVENC ou Quick Sync sur Linux. En cas d’échec, la passe est refaite avec libx264.',
  'feat.bridge.5': 'Les fichiers que le navigateur décode lui-même passent sans traitement. Le préparé reste en cache et est évincé selon la dernière utilisation.',
  'feat.bridge.6': 'Le serveur retrouve les fichiers déposés sur le disque par nom et taille et prend le reste du même dossier. Les dossiers où des fichiers ont déjà été trouvés sont vérifiés en premier.',
  'feat.bridge.7': 'La limite du cache se règle avec une barre dans les réglages, de 4 Go jusqu’à ce que le disque peut contenir.',
  'feat.play': 'Lecture et file d’attente',
  'feat.play.1': 'Ajout : des fichiers, un dossier, un glisser-déposer, l’explorateur de disque. Un dossier choisi ou déposé est lu avec ses sous-dossiers.',
  'feat.play.2': 'Trier par nom, inverser, mélanger, changer l’ordre des fichiers à la main.',
  'feat.play.3': 'Deux vues de liste : lignes et grille. Une ligne montre une image du fichier aux proportions de la vidéo, le nom, la durée, la taille et le nombre de pistes. La grille ne montre que les images.',
  'feat.play.4': 'Le bouton en forme de viseur dans l’en-tête de la file d’attente fait défiler la liste jusqu’au fichier en cours. Quand un autre fichier commence, la liste défile d’elle-même jusqu’à lui, ce qui se désactive dans les réglages.',
  'feat.play.5': 'Enchaînement vers le fichier suivant. Répétition de la file ou d’un fichier. Une carte de fin.',
  'feat.play.6': 'Vitesse de 0.5× à 2×. Déplacement à la souris et au clavier, une indication d’heure au-dessus de la barre, un repère de mise en mémoire tampon.',
  'feat.play.7': 'La position de lecture est retenue pour chaque fichier et marquée dans la file d’attente par un trait fin en bas de l’image. Le volume est retenu aussi.',
  'feat.play.8': 'Avec le serveur local, un rechargement de la page ramène la file d’attente et le fichier où vous vous êtes arrêté.',
  'feat.ui': 'Interface',
  'feat.ui.1': 'Dix langues, déterminées par celle du navigateur.',
  'feat.ui.2': 'Deux polices au choix.',
  'feat.ui.3': 'Les raccourcis sont liés aux codes physiques des touches et marchent dans toutes les dispositions.',
  'feat.ui.4': 'La barre de commandes se masque seule, la favicône montre l’état. Dans les réglages : le comportement du panneau des fichiers, l’ordre des fichiers à la main, le défilement de la file d’attente jusqu’au fichier en cours, le masquage des contrôles lors de l’enchaînement, la police, la langue.',
  'feat.ui.5': 'Quand la place manque, par exemple à côté de la file ouverte, la barre de commandes se resserre : la vitesse, la répétition et l’enchaînement se replient dans un engrenage en bas à droite et s’ouvrent au survol, le nom du studio sur le bouton de piste audio raccourcit. S’il reste moins de quatre lettres, le bouton ne garde que l’icône.',
  'feat.ui.6': 'Les noms de fichier et les chemins longs sont coupés à droite, l’infobulle au survol les montre en entier.',
