  'help.title': 'Pourquoi il n’y a pas de son',
  'help.p1': 'Dans les releases MKV, le son est en général en <b>AC-3, E-AC-3 ou DTS</b>. Le navigateur ne décode pas ces codecs : l’image défile, le son reste muet. Changer de piste n’y fait rien : Chrome n’a pas d’API de changement de piste pour les fichiers locaux.',
  'help.p2': 'Un serveur local reposant sur votre propre ffmpeg règle le problème. Il lit la liste des pistes et réencode celle qui est choisie en AAC, tandis que la vidéo passe sans recompression.',
  'help.p3': 'Ouvrez ensuite <b>http://127.0.0.1:8777</b>. Le bouton « Parcourir le disque » et la liste des pistes audio avec leurs langues apparaîtront.',

