  'empty.text': 'Un enlace a un anime o a un episodio<br>Lapka encuentra los episodios y los doblajes por sí misma',
  'about.lead': 'Lapka es un reproductor de anime local.',

  'feat.pip': 'Imagen en imagen',
  'feat.pip.1': 'Modo navegador: una ventana sin barra de direcciones, controles del navegador. Anterior y siguiente pasan por la API Media Session.',
  'feat.pip.2': 'Modo ampliado: el vídeo pasa a la ventana flotante con la barra de tiempo, el cambio de episodio, el volumen y la elección de pista de audio y subtítulos. La ventana principal sigue funcionando entera: la velocidad, la repetición, el avance automático, la cola, los ajustes y la pantalla completa se quedan allí. Los cambios en una ventana se ven al momento en la otra.',
  'feat.pip.2.1': 'Los atajos funcionan también en la ventana flotante.',
  'feat.pip.2.2': 'Chrome dibuja la barra de direcciones del sitio encima de esta ventana y no se puede quitar, por eso el modo del navegador es el predeterminado.',
  'feat.pip.3': 'En ambos modos, la ventana principal muestra en lugar del vídeo una pantalla de espera con el botón «Traer de vuelta». Si la cola estaba cerrada, se abre en la ventana principal mientras dura la imagen en imagen, para cambiar de episodio desde allí, y vuelve a cerrarse al cerrar la ventana flotante.',
  'feat.audio': 'Sonido y subtítulos',
  'feat.audio.1': 'En la lista de pistas: idioma, nombre del estudio, códec, canales, tasa de bits y frecuencia de muestreo.',
  'feat.audio.2': 'La elección de pista de audio se mantiene al cambiar de archivo. Primero se busca el mismo conjunto de pistas, luego una coincidencia de idioma y estudio, luego solo de idioma.',
  'feat.audio.3': 'Los subtítulos de texto (SRT, ASS, SSA, WebVTT, mov_text) se convierten a WebVTT y se adjuntan al vídeo. Los subtítulos en imagen (PGS, VOBSUB) aparecen en la lista pero no se pueden elegir.',
  'feat.audio.4': 'La elección de subtítulos se mantiene igual. Tamaño, fondo y altura son ajustables.',
  'feat.audio.5': 'La elección de pista y los subtítulos solo funcionan con el servidor local.',
  'feat.bridge': 'El servidor ffmpeg local',
  'feat.bridge.1': 'Una pasada de ffmpeg por archivo y pista: el vídeo se copia en flujo, solo se recodifica a AAC estéreo la pista de audio elegida.',
  'feat.bridge.2': 'El resultado se sirve con HTTP Range. Del desplazamiento se encarga el navegador.',
  'feat.bridge.3': 'El siguiente archivo se prepara en segundo plano, con la pista de audio elegida.',
  'feat.bridge.4': 'Codificación por hardware si el vídeo sí hay que recodificarlo: videotoolbox en macOS, NVENC, Quick Sync o AMF en Windows, NVENC o Quick Sync en Linux. Si falla, la pasada se repite con libx264.',
  'feat.bridge.5': 'Los archivos que el navegador decodifica por sí mismo se sirven sin tocar. Lo preparado queda en caché y se descarta por uso menos reciente.',
  'feat.bridge.6': 'El servidor encuentra en el disco los archivos arrastrados por nombre y tamaño y toma el resto de la misma carpeta. Las carpetas donde ya se encontraron archivos se revisan primero.',
  'feat.bridge.7': 'El límite de la caché se fija con una barra en los ajustes, desde 4 GB hasta lo que cabe en el disco.',
  'feat.play': 'Reproducción y cola',
  'feat.play.1': 'Añadir: archivos, una carpeta, arrastrar y soltar, el explorador de disco. Una carpeta elegida o arrastrada se lee con sus subcarpetas.',
  'feat.play.2': 'Ordenar por nombre, invertir, mezclar, cambiar el orden de los archivos a mano.',
  'feat.play.3': 'Dos vistas de lista: filas y rejilla. En una fila hay un fotograma del archivo con las proporciones del vídeo, el nombre, la duración, el tamaño y el número de pistas. En la rejilla, solo fotogramas.',
  'feat.play.4': 'El botón con la mira en la cabecera de la cola desplaza la lista hasta el archivo actual. Cuando empieza otro archivo, la lista se desplaza sola hasta él, y esto se desactiva en los ajustes.',
  'feat.play.5': 'Avance al siguiente archivo. Repetición de la cola o de un archivo. Al final una tarjeta de resumen.',
  'feat.play.6': 'Velocidad de 0.5× a 2×. Desplazamiento con ratón y teclado, indicación de tiempo sobre la barra, marca de lo almacenado.',
  'feat.play.7': 'La posición de reproducción se recuerda para cada archivo y se marca en la cola con una línea fina en la parte inferior del fotograma. El volumen también se recuerda.',
  'feat.play.8': 'Con el servidor local, al recargar la página vuelven la cola y el archivo donde se quedó.',
  'feat.ui': 'Interfaz',
  'feat.ui.1': 'Diez idiomas, determinado por el del navegador.',
  'feat.ui.2': 'Dos tipografías a elegir.',
  'feat.ui.3': 'Los atajos están atados a los códigos físicos de las teclas y funcionan en cualquier distribución.',
  'feat.ui.4': 'La barra de control se oculta sola, el favicon muestra el estado. En los ajustes: el comportamiento del panel de archivos, el orden de los archivos a mano, desplazar la cola hasta el archivo actual, ocultar los controles al avanzar automáticamente, la fuente, el idioma.',
  'feat.ui.5': 'Cuando falta espacio, por ejemplo junto a la cola abierta, la barra de control se compacta: la velocidad, la repetición y el avance automático se pliegan en un engranaje abajo a la derecha y se abren al pasar el ratón, el nombre del estudio en el botón de pista de audio se acorta. Si quedan menos de cuatro letras, el botón muestra solo el icono.',
  'feat.ui.6': 'Los nombres de archivo y las rutas largas se recortan por la derecha, y al pasar el ratón se ven enteros en la descripción emergente.',
