  'empty.title': 'Incolla un link',
  'empty.text': 'Un link a un anime o a un episodio<br>Lapka trova da sola gli episodi e i doppiaggi',
  'about.lead': 'Lapka è un player di anime locale.',

  'feat.pip': 'Picture-in-picture',
  'feat.pip.1': 'Modalità browser: una finestra senza barra degli indirizzi, controlli del browser. Precedente e successivo passano dall’API Media Session.',
  'feat.pip.2': 'Modalità estesa: il video passa nella finestra flottante con barra di scorrimento, cambio di episodio, volume, scelta della traccia audio e dei sottotitoli. La finestra principale resta del tutto funzionante: velocità, ripetizione, avanzamento automatico, coda, impostazioni e schermo intero restano lì. Le modifiche in una finestra si vedono subito nell’altra.',
  'feat.pip.2.1': 'Le scorciatoie valgono anche nella finestra flottante.',
  'feat.pip.2.2': 'Chrome disegna la barra degli indirizzi del sito sopra questa finestra e non si può togliere, per questo la modalità del browser è quella predefinita.',
  'feat.pip.3': 'In entrambe le modalità, nella finestra principale al posto del video c’è una schermata d’attesa con il pulsante «Riporta qui». Se la coda era chiusa, si apre nella finestra principale per tutta la durata del picture-in-picture, così da cambiare episodio da lì, e si richiude quando la finestra flottante viene chiusa.',
  'feat.audio': 'Audio e sottotitoli',
  'feat.audio.1': 'Nell’elenco delle tracce: lingua, nome dello studio, codec, canali, bitrate, frequenza di campionamento.',
  'feat.audio.2': 'La scelta della traccia audio resta al cambio di file. Si cerca prima lo stesso insieme di tracce, poi una corrispondenza di lingua e studio, poi di sola lingua.',
  'feat.audio.3': 'I sottotitoli testuali (SRT, ASS, SSA, WebVTT, mov_text) vengono convertiti in WebVTT e agganciati al video. I sottotitoli a immagini (PGS, VOBSUB) compaiono nell’elenco ma non si possono scegliere.',
  'feat.audio.4': 'La scelta dei sottotitoli resta allo stesso modo. Dimensione, sfondo e altezza sono regolabili.',
  'feat.audio.5': 'La scelta della traccia e i sottotitoli funzionano solo con il server locale.',
  'feat.bridge': 'Il server ffmpeg locale',
  'feat.bridge.1': 'Una passata di ffmpeg per file e traccia: il video viene copiato in stream, si ricodifica in AAC stereo solo la traccia audio scelta.',
  'feat.bridge.2': 'Il risultato viene servito con HTTP Range. Allo scorrimento pensa il browser.',
  'feat.bridge.3': 'Il file successivo si prepara in background, con la traccia audio scelta.',
  'feat.bridge.4': 'Codifica hardware se il video va comunque ricodificato: videotoolbox su macOS, NVENC, Quick Sync o AMF su Windows, NVENC o Quick Sync su Linux. In caso di errore la passata si ripete con libx264.',
  'feat.bridge.5': 'I file che il browser decodifica da sé passano senza elaborazione. Il preparato resta in cache e viene scartato per uso meno recente.',
  'feat.bridge.6': 'Il server trova sul disco i file trascinati per nome e dimensione e prende il resto della stessa cartella. Le cartelle dove sono già stati trovati dei file vengono controllate per prime.',
  'feat.bridge.7': 'Il limite della cache si imposta con una barra nelle impostazioni, da 4 GB fino a quanto può contenere il disco.',
  'feat.play': 'Riproduzione e coda',
  'feat.play.1': 'Aggiunta: file, una cartella, trascinamento, l’esploratore del disco. Una cartella scelta o trascinata viene letta con le sue sottocartelle.',
  'feat.play.2': 'Ordinare per nome, invertire, mescolare, cambiare a mano l’ordine dei file.',
  'feat.play.3': 'Due viste della lista: righe e griglia. In una riga ci sono un fotogramma del file nelle proporzioni del video, il nome, la durata, la dimensione e il numero di tracce. Nella griglia solo i fotogrammi.',
  'feat.play.4': 'Il pulsante con il mirino nell’intestazione della coda scorre l’elenco fino al file corrente. Quando parte un altro file, l’elenco scorre da solo fino a quel file, e lo si può disattivare nelle impostazioni.',
  'feat.play.5': 'Avanzamento al file successivo. Ripetizione della coda o di un file. Alla fine una scheda riepilogativa.',
  'feat.play.6': 'Velocità da 0.5× a 2×. Scorrimento con mouse e tastiera, suggerimento del tempo sopra la barra, indicatore del buffer.',
  'feat.play.7': 'La posizione di visione viene ricordata per ogni file e segnata nella coda da una linea sottile in fondo al fotogramma. Anche il volume viene ricordato.',
  'feat.play.8': 'Con il server locale, ricaricando la pagina tornano la coda e il file dove ti eri fermato.',
  'feat.ui': 'Interfaccia',
  'feat.ui.1': 'Dieci lingue, determinata da quella del browser.',
  'feat.ui.2': 'Due caratteri a scelta.',
  'feat.ui.3': 'Le scorciatoie sono legate ai codici fisici dei tasti e funzionano con qualsiasi layout.',
  'feat.ui.4': 'La barra dei comandi si nasconde da sola, la favicon mostra lo stato. Nelle impostazioni: il comportamento del pannello dei file, l’ordine dei file a mano, scorrere la coda fino al file corrente, nascondere i controlli durante l’avanzamento automatico, il carattere, la lingua.',
  'feat.ui.5': 'Quando manca spazio, per esempio accanto alla coda aperta, la barra dei comandi si compatta: velocità, ripetizione e avanzamento automatico si raccolgono in un ingranaggio in basso a destra e si aprono al passaggio del mouse, il nome dello studio sul pulsante della traccia audio si accorcia. Se restano meno di quattro lettere, il pulsante mostra solo l’icona.',
  'feat.ui.6': 'I nomi dei file e i percorsi lunghi vengono tagliati a destra, e interi si vedono nel suggerimento al passaggio del mouse.',
  'empty.files': 'Scegli i file',
