  'help.title': 'Perché non c’è audio',
  'help.p1': 'Nelle release MKV l’audio è di solito in <b>AC-3, E-AC-3 o DTS</b>. Il browser non decodifica questi codec: l’immagine scorre, l’audio resta muto. Cambiare traccia non serve: Chrome non ha API di cambio traccia per i file locali.',
