  'about.lead': 'A Lapka é um player de anime local.',

  'feat.pip': 'Picture-in-picture',
  'feat.pip.1': 'Modo navegador: uma janela sem barra de endereço, controles do navegador. Anterior e próximo passam pela API Media Session.',
  'feat.pip.2': 'Modo estendido: o vídeo vai para a janela flutuante com barra de tempo, troca de episódio, volume, escolha da faixa de áudio e das legendas. A janela principal continua funcionando por inteiro: velocidade, repetição, avanço automático, fila, configurações e tela cheia ficam lá. Mudanças em uma janela aparecem na hora na outra.',
  'feat.pip.2.1': 'Os atalhos valem também na janela flutuante.',
  'feat.pip.2.2': 'O Chrome desenha a barra de endereço do site no topo desta janela e ela não pode ser removida, por isso o modo do navegador é o padrão.',
  'feat.pip.3': 'Nos dois modos, a janela principal mostra no lugar do vídeo uma tela de espera com o botão «Trazer de volta». Se a fila estava fechada, ela abre na janela principal enquanto dura o picture-in-picture, para trocar de episódio por lá, e fecha de novo quando a janela flutuante é fechada.',
  'feat.audio': 'Áudio e legendas',
  'feat.audio.1': 'Na lista de faixas: idioma, nome do estúdio, codec, canais, taxa de bits, taxa de amostragem.',
  'feat.audio.2': 'A escolha da faixa de áudio se mantém ao trocar de arquivo. Procura-se primeiro o mesmo conjunto de faixas, depois uma correspondência de idioma e estúdio, depois só de idioma.',
  'feat.audio.3': 'Legendas de texto (SRT, ASS, SSA, WebVTT, mov_text) são convertidas para WebVTT e anexadas ao vídeo. Legendas em imagem (PGS, VOBSUB) aparecem na lista, mas não podem ser escolhidas.',
  'feat.audio.4': 'A escolha das legendas se mantém do mesmo jeito. Tamanho, fundo e altura são ajustáveis.',
  'feat.audio.5': 'A escolha da faixa e as legendas só funcionam com o servidor local.',
  'feat.bridge': 'O servidor ffmpeg local',
  'feat.bridge.1': 'Uma passada de ffmpeg por arquivo e faixa: o vídeo é copiado em fluxo, só a faixa de áudio escolhida é recodificada para AAC estéreo.',
  'feat.bridge.2': 'O resultado é servido com HTTP Range. Quem navega é o navegador.',
  'feat.bridge.3': 'O próximo arquivo é preparado em segundo plano, com a faixa de áudio escolhida.',
  'feat.bridge.4': 'Codificação por hardware se o vídeo tiver mesmo que ser recodificado: videotoolbox no macOS, NVENC, Quick Sync ou AMF no Windows, NVENC ou Quick Sync no Linux. Em caso de falha, a passada se repete com libx264.',
  'feat.bridge.5': 'Arquivos que o navegador decodifica sozinho são servidos sem tratamento. O preparado fica em cache e é descartado por uso menos recente.',
  'feat.bridge.6': 'O servidor encontra no disco os arquivos arrastados por nome e tamanho e leva o resto da mesma pasta. As pastas onde arquivos já foram encontrados são verificadas primeiro.',
  'feat.bridge.7': 'O limite do cache é definido com uma barra nas configurações, de 4 GB até o que cabe no disco.',
  'feat.play': 'Reprodução e fila',
  'feat.play.1': 'Adicionar: arquivos, uma pasta, arrastar e soltar, o explorador de disco. Uma pasta escolhida ou arrastada é lida com as suas subpastas.',
  'feat.play.2': 'Ordenar por nome, inverter, embaralhar, mudar a ordem dos arquivos à mão.',
  'feat.play.3': 'Duas visões da lista: linhas e grade. Numa linha ficam um quadro do arquivo nas proporções do vídeo, o nome, a duração, o tamanho e o número de faixas. Na grade, só os quadros.',
  'feat.play.4': 'O botão com a mira no cabeçalho da fila rola a lista até o arquivo atual. Quando outro arquivo começa, a lista rola sozinha até ele, e isso se desliga nas configurações.',
  'feat.play.5': 'Avanço para o próximo arquivo. Repetição da fila ou de um arquivo. No fim um cartão de resumo.',
  'feat.play.6': 'Velocidade de 0.5× a 2×. Navegação por mouse e teclado, dica de tempo acima da barra, marca de buffer.',
  'feat.play.7': 'A posição de reprodução é lembrada para cada arquivo e marcada na fila por uma linha fina na parte de baixo do quadro. O volume também é lembrado.',
  'feat.play.8': 'Com o servidor local, ao recarregar a página voltam a fila e o arquivo onde você parou.',
  'feat.ui': 'Interface',
  'feat.ui.1': 'Dez idiomas, determinado pelo do navegador.',
  'feat.ui.2': 'Duas fontes à escolha.',
  'feat.ui.3': 'Os atalhos ficam presos aos códigos físicos das teclas e funcionam em qualquer layout.',
  'feat.ui.4': 'A barra de controle se esconde sozinha, o favicon mostra o estado. Nas configurações: o comportamento do painel de arquivos, a ordem dos arquivos à mão, rolar a fila até o arquivo atual, ocultar os controles no avanço automático, a fonte, o idioma.',
  'feat.ui.5': 'Quando falta espaço, por exemplo ao lado da fila aberta, a barra de controle se compacta: velocidade, repetição e avanço automático se recolhem numa engrenagem no canto inferior direito e abrem ao passar o mouse, o nome do estúdio no botão da faixa de áudio encurta. Se restarem menos de quatro letras, o botão mostra só o ícone.',
  'feat.ui.6': 'Nomes de arquivo e caminhos longos são cortados à direita, e inteiros aparecem na dica ao passar o mouse.',
