  'feat.pip.2': 'Tryb rozszerzony: do pływającego okna trafia wideo z paskiem przewijania, przełączaniem odcinków, głośnością, wyborem ścieżki dźwiękowej i napisów. Główne okno działa w pełni: prędkość, powtarzanie, automatyczne przejście, kolejka, ustawienia i pełny ekran zostają w nim. Zmiany w jednym oknie od razu widać w drugim.',
  'feat.pip.2.1': 'Skróty działają też w pływającym oknie.',
  'feat.pip.2.2': 'Chrome rysuje pasek adresu strony nad tym oknem i nie da się go usunąć, dlatego domyślnie ustawiony jest tryb przeglądarki.',
  'feat.pip.3': 'W obu trybach w głównym oknie w miejscu wideo jest plansza z przyciskiem „Przywróć tutaj”. Jeśli kolejka była zamknięta, na czas trybu obraz w obrazie otwiera się w głównym oknie, żeby stamtąd przełączać odcinki, a po zamknięciu pływającego okna znowu się zamyka.',
  'feat.audio': 'Dźwięk i napisy',
  'feat.audio.1': 'Na liście ścieżek: język, nazwa studia, kodek, kanały, bitrate, częstotliwość próbkowania.',
  'feat.audio.2': 'Wybór ścieżki dźwiękowej zostaje przy zmianie pliku. Najpierw szukany jest ten sam zestaw ścieżek, potem zgodność języka i studia, potem samego języka.',
  'feat.audio.3': 'Napisy tekstowe (SRT, ASS, SSA, WebVTT, mov_text) są konwertowane na WebVTT i podpinane do wideo. Napisy obrazkowe (PGS, VOBSUB) widać na liście, ale nie można ich wybrać.',
  'feat.audio.4': 'Wybór napisów zostaje tak samo. Rozmiar, tło i wysokość są regulowane.',
  'feat.audio.5': 'Wybór ścieżki i napisy działają tylko z lokalnym serwerem.',
  'feat.bridge': 'Lokalny serwer na ffmpeg',
  'feat.bridge.1': 'Jedno przejście ffmpeg na plik i ścieżkę: wideo kopiowane strumieniowo, na AAC stereo przekodowywana jest tylko wybrana ścieżka dźwiękowa.',
  'feat.bridge.2': 'Wynik jest oddawany z HTTP Range. Przewijaniem zajmuje się przeglądarka.',
  'feat.bridge.3': 'Następny plik przygotowuje się w tle, z wybraną ścieżką dźwiękową.',
  'feat.bridge.4': 'Kodowanie sprzętowe, jeśli wideo jednak trzeba przekodować: videotoolbox na macOS, NVENC, Quick Sync albo AMF na Windows, NVENC albo Quick Sync na Linux. Przy błędzie przejście powtarza się na libx264.',
  'feat.bridge.5': 'Pliki, które przeglądarka dekoduje sama, idą bez obróbki. Przygotowane leżą w pamięci podręcznej i są wypierane wedle ostatniego użycia.',
  'feat.bridge.6': 'Serwer znajduje na dysku przeciągnięte pliki po nazwie i rozmiarze i bierze resztę tego samego folderu. Foldery, w których pliki już się znalazły, sprawdza najpierw.',
  'feat.bridge.7': 'Limit pamięci podręcznej ustawia pasek w ustawieniach: od 4 GB do tego, co zmieści dysk.',
  'feat.play': 'Odtwarzanie i kolejka',
  'feat.play.1': 'Dodawanie: pliki, folder, przeciąganie, przeglądarka dysku. Wybrany albo przeciągnięty folder jest czytany razem z podfolderami.',
  'feat.play.2': 'Sortowanie po nazwie, odwrócenie, wymieszanie, ręczna zmiana kolejności plików.',
  'feat.play.3': 'Dwa widoki listy: wiersze i siatka. W wierszu jest klatka z pliku w proporcjach wideo, nazwa, czas, rozmiar i liczba ścieżek. W siatce same klatki.',
  'feat.play.4': 'Przycisk z celownikiem w nagłówku kolejki przewija listę do bieżącego pliku. Gdy zaczyna się inny plik, lista sama przewija się do niego, można to wyłączyć w ustawieniach.',
  'feat.play.5': 'Przejście do następnego pliku. Powtarzanie kolejki albo jednego pliku. Na końcu podsumowanie.',
  'feat.play.6': 'Prędkość od 0.5× do 2×. Przewijanie myszą i klawiaturą, podpowiedź czasu nad paskiem, znacznik bufora.',
  'feat.play.7': 'Miejsce odtwarzania jest zapamiętywane dla każdego pliku i zaznaczone w kolejce cienką linią na dole klatki. Głośność też jest zapamiętywana.',
  'feat.play.8': 'Z lokalnym serwerem po przeładowaniu strony wracają kolejka i plik, na którym przerwano.',
  'feat.ui': 'Interfejs',
  'feat.ui.1': 'Dziesięć języków, ustalany po języku przeglądarki.',
  'feat.ui.2': 'Dwa kroje pisma do wyboru.',
  'feat.ui.3': 'Skróty są przypięte do fizycznych kodów klawiszy i działają w każdym układzie.',
  'feat.ui.4': 'Panel sterowania chowa się sam, stan pokazuje favikona. W ustawieniach: zachowanie panelu plików, ręczna zmiana kolejności plików, przewijanie kolejki do bieżącego pliku, ukrywanie panelu przy automatycznym przejściu, czcionka, język.',
  'feat.ui.5': 'Gdy brakuje miejsca, na przykład obok otwartej kolejki, panel sterowania się zagęszcza: prędkość, powtarzanie i automatyczne przejście zwijają się w zębatkę w prawym dolnym rogu i rozwijają po najechaniu, nazwa studia na przycisku ścieżki dźwiękowej się skraca. Gdy zostają mniej niż cztery litery, na przycisku zostaje sama ikona.',
  'feat.ui.6': 'Długie nazwy plików i ścieżki są ucinane z prawej, w całości widać je w podpowiedzi po najechaniu.',
