  'help.title': 'Dlaczego nie ma dźwięku',
  'help.p1': 'W wydaniach MKV dźwięk jest zwykle w <b>AC-3, E-AC-3 lub DTS</b>. Przeglądarka tych kodeków nie dekoduje: obraz leci, dźwięk milczy. Wybór innej ścieżki nic nie da: Chrome nie ma API przełączania ścieżek dla plików lokalnych.',
  'help.p2': 'Rozwiązuje to lokalny serwer na twoim własnym ffmpeg. Czyta listę ścieżek i przekodowuje wybraną na AAC, a wideo oddaje bez ponownej kompresji.',
