  'feat.pip': 'Resim içinde resim',
  'feat.pip.1': 'Tarayıcı kipi: adres çubuğu olmayan bir pencere, tarayıcı denetimleri. Önceki ve sonraki Media Session API üzerinden gider.',
  'feat.pip.2': 'Genişletilmiş kip: yüzen pencereye sarma çubuğu, bölüm geçişi, ses düzeyi, ses parçası ve altyazı seçimiyle birlikte video geçer. Ana pencere tümüyle çalışır durumda kalır: hız, tekrar, otomatik geçiş, sıra, ayarlar ve tam ekran orada kalır. Bir pencerede yapılan değişiklik öbüründe hemen görünür.',
  'feat.pip.2.1': 'Kısayollar yüzen pencerede de çalışır.',
  'feat.pip.2.2': 'Chrome bu pencerenin üstüne sitenin adres çubuğunu çizer ve bu çubuk kaldırılamaz, bu yüzden varsayılan kip tarayıcı kipidir.',
  'feat.pip.3': 'İki kipte de ana pencerede videonun yerinde «Buraya geri al» düğmeli bir yer tutucu durur. Sıra kapalıysa resim içinde resim sürdüğü sürece ana pencerede açılır, böylece bölümler oradan değiştirilebilir, yüzen pencere kapanınca da yeniden kapanır.',
  'feat.audio': 'Ses ve altyazılar',
  'feat.audio.1': 'Parça listesinde: dil, stüdyo adı, kodek, kanal sayısı, bit hızı, örnekleme frekansı.',
  'feat.audio.2': 'Ses parçası seçimi dosya değişince korunur. Önce aynı parça kümesi aranır, sonra dil ile stüdyo eşleşmesi, sonra yalnızca dil.',
  'feat.audio.3': 'Metin altyazılar (SRT, ASS, SSA, WebVTT, mov_text) WebVTT’ye çevrilip videoya bağlanır. Görüntü altyazılar (PGS, VOBSUB) listede görünür ama seçilemez.',
  'feat.audio.4': 'Altyazı seçimi de aynı şekilde korunur. Boyut, zemin ve yükseklik ayarlanabilir.',
  'feat.audio.5': 'Ses parçası seçimi ve altyazılar yalnızca yerel sunucuyla çalışır.',
  'feat.bridge': 'Yerel ffmpeg sunucusu',
  'feat.bridge.1': 'Dosya ve parça başına tek ffmpeg geçişi: video akış olarak kopyalanır, yalnızca seçilen ses parçası stereo AAC’ye çevrilir.',
  'feat.bridge.2': 'Sonuç HTTP Range ile sunulur. Sarma işini tarayıcı yapar.',
  'feat.bridge.3': 'Sonraki dosya, seçilen ses parçasıyla arka planda hazırlanır.',
  'feat.bridge.4': 'Video yine de yeniden kodlanacaksa donanım kodlaması: macOS’ta videotoolbox, Windows’ta NVENC, Quick Sync ya da AMF, Linux’ta NVENC ya da Quick Sync. Hata olursa geçiş libx264 ile yinelenir.',
  'feat.bridge.5': 'Tarayıcının kendi çözdüğü dosyalar işlenmeden geçer. Hazırlananlar önbellekte durur ve en az kullanılana göre atılır.',
  'feat.bridge.6': 'Sunucu sürüklenen dosyaları diskte ada ve boyuta göre bulur ve aynı klasörün geri kalanını da alır. Daha önce dosya bulunan klasörlere önce bakılır.',
  'feat.bridge.7': 'Önbellek sınırı ayarlardaki bir çubukla belirlenir: 4 GB’tan diskin alabileceği kadarına.',
  'feat.play': 'Oynatma ve sıra',
  'feat.play.1': 'Ekleme: dosyalar, bir klasör, sürükle bırak, disk gezgini. Seçilen ya da sürüklenen klasör alt klasörleriyle birlikte okunur.',
  'feat.play.2': 'Ada göre sıralama, ters çevirme, karıştırma, dosya sırasını elle değiştirme.',
  'feat.play.3': 'İki liste görünümü: satırlar ve ızgara. Satırda dosyadan videonun oranlarında bir kare, ad, süre, boyut ve parça sayısı bulunur. Izgarada yalnızca kareler vardır.',
  'feat.play.4': 'Sıranın başlığındaki nişangâh düğmesi listeyi geçerli dosyaya kaydırır. Başka bir dosya başladığında liste kendiliğinden ona kayar, bu ayarlardan kapatılabilir.',
  'feat.play.5': 'Sonraki dosyaya geçiş. Sıranın ya da tek dosyanın tekrarı. Sonda bir özet kartı.',
  'feat.play.6': '0.5× ile 2× arası hız. Fare ve klavyeyle sarma, çubuğun üstünde zaman ipucu, arabellek işareti.',
  'feat.play.7': 'İzleme konumu her dosya için hatırlanır ve sırada karenin altındaki ince bir çizgiyle gösterilir. Ses düzeyi de hatırlanır.',
  'feat.play.8': 'Yerel sunucuyla sayfa yeniden yüklenince sıra ve kalınan dosya geri gelir.',
  'feat.ui': 'Arayüz',
  'feat.ui.1': 'On dil, tarayıcının diline göre belirlenir.',
  'feat.ui.2': 'İki yazı tipi seçeneği.',
  'feat.ui.3': 'Kısayollar fiziksel tuş kodlarına bağlıdır ve her düzende çalışır.',
  'feat.ui.4': 'Denetim çubuğu kendini gizler, durumu favicon gösterir. Ayarlarda: dosya panelinin davranışı, dosya sırasını elle değiştirme, sırayı geçerli dosyaya kaydırma, otomatik geçişte denetimleri gizleme, yazı tipi, dil.',
  'feat.ui.5': 'Yer daraldığında, örneğin açık sıranın yanında, denetim çubuğu sıkışır: hız, tekrar ve otomatik geçiş sağ alttaki bir dişliye katlanır ve üzerine gelince açılır, ses parçası düğmesindeki stüdyo adı kısalır. Dörtten az harf kalırsa düğmede yalnızca simge kalır.',
  'feat.ui.6': 'Uzun dosya adları ve yollar sağdan kesilir, tamamı üzerine gelince açılan ipucunda görünür.',
