  'feat.pip.2': '增强模式：视频进入悬浮窗，带进度条、切换剧集、音量、音轨与字幕的选择。主窗口仍然完整可用：倍速、重复、自动播放下一个、播放列表、设置和全屏都留在那里。一个窗口里的改动会立刻显示在另一个窗口里。',
