  'feat.audio.2': '切换文件时音轨的选择会保留。先找同一套音轨，再找语言和译制方都对上的，最后只按语言。',
  'feat.audio.3': '文本字幕（SRT、ASS、SSA、WebVTT、mov_text）转成 WebVTT 挂到视频上。图像字幕（PGS、VOBSUB）会列出，但不能选择。',
  'feat.audio.4': '字幕的选择同样保留。大小、衬底和高度可调。',
