  'feat.bridge.2': '结果带 HTTP Range 提供。拖动由浏览器完成。',
  'feat.bridge.3': '下一个文件在后台准备，并沿用所选的音轨。',
  'feat.bridge.4': '视频确实需要重新编码时用硬件编码：macOS 上 videotoolbox，Windows 上 NVENC、Quick Sync 或 AMF，Linux 上 NVENC 或 Quick Sync。出错就用 libx264 再跑一遍。',
