  'feat.play.2': '按名称排序、倒序、随机、手动调整文件顺序。',
  'feat.play.3': '两种列表视图：行和网格。每一行有按视频比例显示的文件画面、名称、时长、大小和音轨数。网格里只有画面。',
  'feat.play.4': '播放列表顶栏里的准星按钮会把列表滚动到当前文件。换到另一个文件时，列表会自动滚动到它，这可以在设置里关闭。',
  'feat.play.5': '自动播放下一个文件。重复整个列表或单个文件。播完后一张汇总卡片。',
  'feat.play.6': '0.5× 到 2× 的倍速。用鼠标和键盘拖动，进度条上方的时间提示，已缓冲的标记。',
  'feat.play.7': '每个文件的观看位置都会记住，并在播放列表里用画面底部的一条细线标出。音量也会记住。',
  'feat.play.8': '本地服务运行时，刷新页面后播放列表和上次停下的文件会回来。',
