  'feat.ui.4': '控制栏自动隐藏，状态由网站图标显示。设置里有：文件面板的行为、手动调整文件顺序、播放列表滚动到当前文件、自动切换时隐藏控制栏、字体、语言。',
  'feat.ui.5': '空间不够时，比如播放列表开着的时候，控制栏会收紧：倍速、重复和自动播放下一个收进右下角的齿轮，鼠标移上去才展开；音轨按钮上的工作室名称会变短，剩不到四个字符时只显示图标。',
